import secrets, hashlib, hmac

def ct_compare(a, b):
    return hmac.compare_digest(a, b)

def hash_pwd(pwd):
    salt = secrets.token_hex(16)
    h = hashlib.pbkdf2_hmac('sha256', pwd.encode(), salt.encode(), 100000)
    return f'{salt}${h.hex()}'

def verify_pwd(pwd, stored):
    salt, hash_hex = stored.split('$')
    h = hashlib.pbkdf2_hmac('sha256', pwd.encode(), salt.encode(), 100000)
    return ct_compare(h.hex(), hash_hex)

# Tests
stored = hash_pwd('secret')
assert verify_pwd('secret', stored)
assert not verify_pwd('bad', stored)
